"use client";

import { useState, useTransition } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { resendSignupCodeAction, verifySignupAction } from "@/app/auth/actions";
import { Spinner, Alert } from "@/components/ui";

/**
 * Signup step 3 — retype the code.
 *
 * No email is sent. The code is generated by `nm_issue_code()` and shown on
 * this screen; the user types it back. It rotates: a wrong entry immediately
 * issues a new code, which is displayed, so the user is never looking at a
 * code that has already been invalidated.
 */
export function VerifyEmail({
  email,
  role,
  initialCode,
}: {
  email: string;
  role: string;
  initialCode: string;
}) {
  const router = useRouter();
  const [code, setCode] = useState(initialCode);
  const [shown, setShown] = useState(initialCode);
  const [typed, setTyped] = useState("");
  const [err, setErr] = useState("");
  const [attemptsLeft, setAttemptsLeft] = useState<number | null>(null);
  const [pending, startTransition] = useTransition();
  const [resending, startResend] = useTransition();

  function submit(e: React.FormEvent) {
    e.preventDefault();
    setErr("");

    if (!/^\d{6}$/.test(typed.trim())) {
      setErr("Enter the 6-digit code shown above.");
      return;
    }

    const fd = new FormData();
    fd.set("email", email);
    fd.set("code", typed.trim());
    fd.set("role", role);

    startTransition(async () => {
      const result = await verifySignupAction(fd);
      if (!result.ok) {
        setErr(result.error);
        if (result.code) {
          // The code rotated — show the new one and clear the box.
          setShown(result.code);
          setCode(result.code);
          setTyped("");
        }
        if (typeof result.attemptsLeft === "number") setAttemptsLeft(result.attemptsLeft);
        return;
      }
      router.push(result.next ?? "/");
      router.refresh();
    });
  }

  function resend() {
    setErr("");
    const fd = new FormData();
    fd.set("email", email);
    startResend(async () => {
      const result = await resendSignupCodeAction(fd);
      if (!result.ok) {
        setErr(result.error);
        return;
      }
      setShown(result.code ?? "");
      setCode(result.code ?? "");
      setTyped("");
      setAttemptsLeft(null);
    });
  }

  return (
    <div className="mx-auto w-full max-w-[420px] text-center">
      <div className="mx-auto grid h-16 w-16 place-items-center rounded-2xl bg-brand-50">
        <svg viewBox="0 0 24 24" className="h-8 w-8 text-brand-600" fill="none" stroke="currentColor" strokeWidth={1.7} strokeLinecap="round" strokeLinejoin="round">
          <rect x="4" y="10" width="16" height="10" rx="2.2" />
          <path d="M8 10V7a4 4 0 0 1 8 0v3" />
        </svg>
      </div>

      <h1 className="mt-5 text-[24px] font-extrabold tracking-tight text-ink-900">Confirm it&apos;s you</h1>
      <p className="mx-auto mt-1.5 max-w-[330px] text-[13.5px] leading-relaxed text-ink-500">
        Type the code below to finish setting up{" "}
        <strong className="font-semibold text-ink-800">{email}</strong>. No email is sent — the code is
        right here.
      </p>

      {/* The code itself. Large, monospaced and selectable, because the user
          has to read it and retype it. */}
      <div className="mt-5 rounded-2xl border-2 border-dashed border-brand-300 bg-brand-50/60 px-4 py-4">
        <p className="text-[11px] font-bold uppercase tracking-wider text-brand-700">Your code</p>
        <p
          className="mt-1 select-all font-mono text-[34px] font-extrabold leading-none tracking-[0.22em] text-brand-800"
          aria-live="polite"
        >
          {shown || "------"}
        </p>
        <p className="mt-2 text-[11.5px] text-ink-500">Expires in 10 minutes.</p>
      </div>

      <form onSubmit={submit} className="mt-5 space-y-3 text-left">
        <div>
          <label className="nm-label" htmlFor="code">Retype the code</label>
          <input
            id="code"
            inputMode="numeric"
            autoComplete="one-time-code"
            maxLength={6}
            value={typed}
            onChange={(e) => setTyped(e.target.value.replace(/\D/g, ""))}
            className="nm-input text-center font-mono text-[22px] tracking-[0.3em]"
            placeholder="000000"
            aria-describedby={err ? "code-error" : undefined}
          />
        </div>

        {err && (
          <p id="code-error" className="text-[12.5px] font-medium text-red-600" role="alert">
            {err}
          </p>
        )}
        {attemptsLeft !== null && attemptsLeft >= 0 && !err && (
          <p className="text-[12px] text-ink-500">{attemptsLeft} tries left before a new code is needed.</p>
        )}

        <button type="submit" disabled={pending} className="nm-btn-primary w-full !py-3">
          {pending ? <><Spinner /> Confirming…</> : "Confirm and continue"}
        </button>
      </form>

      <button
        onClick={resend}
        disabled={resending}
        className="mt-3 w-full text-[12.5px] font-semibold text-brand-600 hover:underline disabled:opacity-60"
      >
        {resending ? "Getting a new code…" : "Show me a different code"}
      </button>

      <Alert tone="blue">
        Keep this code to yourself. NaijaMart will never ask you for it by phone or chat.
      </Alert>

      <p className="mt-4 text-[12.5px] text-ink-500">
        Wrong email?{" "}
        <Link href="/signup/details" className="font-semibold text-brand-600 hover:underline">
          Start again
        </Link>
      </p>
    </div>
  );
}
